//!
//! CA manager (ADR-004): one long-lived root CA per data directory, leaf
//! certificates minted on demand per authority, cached in memory.
//!
//! Persistence model: `ca/cert.pem` + `ca/key.pem` (0600 on unix). The root
//! is ECDSA-P256 and always generated by Aether, so the key algorithm is
//! known when reloading. Leaf signing reuses the rcgen issuer pattern:
//! params are recovered from the stored DER (`from_ca_cert_der`) and the
//! loaded key re-signs — the *stored* DER is what clients see in the chain.

use aether_core::error::{AetherError, AetherResult};
use base64::Engine as _;
use rcgen::{
    BasicConstraints, CertificateParams, DnType, ExtendedKeyUsagePurpose, IsCa, Issuer, KeyPair,
    KeyUsagePurpose,
};
use rustls::pki_types::{CertificateDer, PrivatePkcs8KeyDer};
use rustls::sign::CertifiedKey;
use rustls_pki_types::pem::PemObject as _;
use std::collections::HashMap;
use std::path::PathBuf;
use std::sync::{Arc, Mutex};
use time::OffsetDateTime;

const KEY_ALG: &rcgen::SignatureAlgorithm = &rcgen::PKCS_ECDSA_P256_SHA256;
const CA_CERT_FILE: &str = "ca.cert.pem";
const CA_KEY_FILE: &str = "ca.key.pem";
const LEAF_VALIDITY_DAYS: i64 = 825;
const CA_VALIDITY_DAYS: i64 = 3650;
/// Upper bound on cached leaf certs (audit M3). Evictions are invisible to
/// users: a re-request for an evicted host simply mints a fresh leaf.
const MAX_LEAF_CACHE: usize = 1024;

/// Map of minted leaves plus recency order (LRU: first entry evicted first).
type LeafCache = (HashMap<String, Arc<CertifiedKey>>, Vec<String>);

pub struct CaManager {
    dir: PathBuf,
    ca_der: CertificateDer<'static>,
    /// rcgen 0.14 Issuer: DN + key-identifier + key usages + signing key.
    issuer: Issuer<'static, KeyPair>,
    /// Bounded LRU of minted leaves (audit M3): a scanner hitting random
    /// subdomains must not grow this without limit. Order = Vec of hosts,
    /// least-recently-used first; capacity MAX_LEAF_CACHE.
    cache: Mutex<LeafCache>,
}

impl CaManager {
    /// Loads the persistent CA or creates one on first run.
    pub fn load_or_create(dir: impl Into<PathBuf>) -> AetherResult<Self> {
        let dir = dir.into();
        std::fs::create_dir_all(&dir)
            .map_err(|e| AetherError::storage(format!("create CA dir {}: {e}", dir.display())))?;
        let cert_path = dir.join(CA_CERT_FILE);
        let key_path = dir.join(CA_KEY_FILE);

        let (ca_der, issuer) = match (read_pem_file(&cert_path), read_pem_file(&key_path)) {
            (Some(cert_pem), Some(key_pem)) => {
                let der = pem_to_der(&cert_pem)?;
                let key = KeyPair::from_pkcs8_pem_and_sign_algo(&key_pem, KEY_ALG)
                    .map_err(|e| AetherError::tls(format!("parse CA key: {e}")))?;
                // rcgen 0.14: the issuer is rebuilt straight from the
                // persisted certificate (DN / AKI / key usages) — the
                // chain we serve still uses `der`.
                let issuer = Issuer::from_ca_cert_der(&der, key)
                    .map_err(|e| AetherError::tls(format!("rebuild issuer: {e}")))?;
                (der, issuer)
            }
            (None, None) => Self::generate_and_persist(&cert_path, &key_path)?,
            _ => {
                return Err(AetherError::storage(format!(
                    "incomplete CA in {}: cert and key must exist together",
                    dir.display()
                )));
            }
        };

        Ok(Self {
            dir,
            ca_der,
            issuer,
            cache: Mutex::new((HashMap::new(), Vec::new())),
        })
    }

    fn generate_and_persist(
        cert_path: &std::path::Path,
        key_path: &std::path::Path,
    ) -> AetherResult<(CertificateDer<'static>, Issuer<'static, KeyPair>)> {
        let now = OffsetDateTime::now_utc();
        let mut params = CertificateParams::default();
        params
            .distinguished_name
            .push(DnType::CommonName, "Aether Proxy CA");
        params
            .distinguished_name
            .push(DnType::OrganizationName, "Aether");
        params.is_ca = IsCa::Ca(BasicConstraints::Unconstrained);
        params.key_usages = vec![
            KeyUsagePurpose::DigitalSignature,
            KeyUsagePurpose::KeyCertSign,
            KeyUsagePurpose::CrlSign,
        ];
        params.not_before = now - time::Duration::days(1);
        params.not_after = now + time::Duration::days(CA_VALIDITY_DAYS);

        let key =
            KeyPair::generate().map_err(|e| AetherError::tls(format!("generate CA key: {e}")))?;
        // rcgen 0.14: CertifiedIssuer bundles the self-signed certificate
        // with its Issuer (DN + key-identifier + usages) in one step.
        let cert = params
            .self_signed(&key)
            .map_err(|e| AetherError::tls(format!("self-sign CA: {e}")))?;

        write_private_file(cert_path, cert.pem().into_bytes())?;
        write_private_file(key_path, key.serialize_pem().into_bytes())?;
        tracing::info!(ca = %cert_path.display(), "generated new proxy CA");
        let ca_der = cert.der().clone();
        // Same rebuild path as the load branch — one issuer shape everywhere.
        let issuer = Issuer::from_ca_cert_der(&ca_der, key)
            .map_err(|e| AetherError::tls(format!("build issuer: {e}")))?;
        Ok((ca_der, issuer))
    }

    /// DER of the root CA (what users install into their trust store).
    pub fn ca_cert_der(&self) -> &CertificateDer<'static> {
        &self.ca_der
    }

    /// Root CA as PEM (for `aether ca export`).
    pub fn ca_cert_pem(&self) -> String {
        der_to_pem(self.ca_der.as_ref())
    }

    /// Directory holding the CA files.
    pub fn dir(&self) -> &std::path::Path {
        &self.dir
    }

    /// Mint (or fetch from cache) the MITM certificate chain + key for a host.
    /// `host` may be a DNS name or an IP literal (bracketed IPv6 accepted).
    pub fn leaf_for(&self, host: &str) -> AetherResult<Arc<CertifiedKey>> {
        let host = host.trim().trim_end_matches('.').to_string();
        let host = host
            .trim_start_matches('[')
            .trim_end_matches(']')
            .to_string();
        if host.is_empty() {
            return Err(AetherError::tls("empty host for leaf certificate"));
        }
        {
            let mut guard = self.cache.lock().expect("ca cache");
            let (map, order) = &mut *guard;
            if let Some(hit) = map.get(&host) {
                // refresh recency
                if let Some(pos) = order.iter().position(|h| h == &host) {
                    let h = order.remove(pos);
                    order.push(h);
                }
                return Ok(hit.clone());
            }
        }

        let now = OffsetDateTime::now_utc();
        let mut params = CertificateParams::new(vec![host.clone()])
            .map_err(|e| AetherError::tls(format!("bad SAN '{host}': {e}")))?;
        params
            .distinguished_name
            .push(DnType::CommonName, host.clone());
        params.is_ca = IsCa::NoCa;
        params.key_usages = vec![KeyUsagePurpose::DigitalSignature];
        params.extended_key_usages = vec![ExtendedKeyUsagePurpose::ServerAuth];
        params.use_authority_key_identifier_extension = true;
        params.not_before = now - time::Duration::days(1);
        params.not_after = now + time::Duration::days(LEAF_VALIDITY_DAYS);

        let leaf_key =
            KeyPair::generate().map_err(|e| AetherError::tls(format!("generate leaf key: {e}")))?;
        let leaf = params
            .signed_by(&leaf_key, &self.issuer)
            .map_err(|e| AetherError::tls(format!("sign leaf for {host}: {e}")))?;

        let key_der = PrivatePkcs8KeyDer::from(leaf_key.serialize_der());
        let signing_key = rustls::crypto::ring::sign::any_supported_type(&key_der.into())
            .map_err(|e| AetherError::tls(format!("load leaf key: {e}")))?;
        let certified = Arc::new(CertifiedKey {
            cert: vec![leaf.der().clone(), self.ca_der.clone()],
            key: signing_key,
            ocsp: None,
        });
        {
            let mut guard = self.cache.lock().expect("ca cache");
            let (map, order) = &mut *guard;
            if map.len() >= MAX_LEAF_CACHE {
                // evict least-recently-used until we are under the cap
                while map.len() >= MAX_LEAF_CACHE {
                    let Some(lru) = order.first().cloned() else {
                        break;
                    };
                    order.remove(0);
                    map.remove(&lru);
                }
            }
            if !map.contains_key(&host) {
                order.push(host.clone());
            }
            map.insert(host, certified.clone());
        }
        Ok(certified)
    }
}

// ── pem helpers (small, dependency-light) ──────────────────────────────────

fn read_pem_file(path: &std::path::Path) -> Option<String> {
    std::fs::read_to_string(path).ok()
}

fn pem_to_der(pem: &str) -> AetherResult<CertificateDer<'static>> {
    // rustls-pemfile is unmaintained (RUSTSEC-2026-xxxx, found by the ADR-018
    // security-audit gate); its successor is the `pem` module in
    // rustls-pki-types itself — same bytes, no extra dependency.
    CertificateDer::pem_slice_iter(pem.as_bytes())
        .next()
        .transpose()
        .map_err(|e| AetherError::tls(format!("decode PEM cert: {e}")))?
        .ok_or_else(|| AetherError::tls("no certificate found in PEM"))
}

/// Minimal PEM encoder for the export command.
fn der_to_pem(der: &[u8]) -> String {
    let b64 = base64::engine::general_purpose::STANDARD.encode(der);
    let mut out = String::from("-----BEGIN CERTIFICATE-----\n");
    for chunk in b64.as_bytes().chunks(64) {
        out.push_str(std::str::from_utf8(chunk).unwrap_or(""));
        out.push('\n');
    }
    out.push_str("-----END CERTIFICATE-----\n");
    out
}

fn write_private_file(path: &std::path::Path, bytes: Vec<u8>) -> AetherResult<()> {
    use std::io::Write;
    // Open with 0600 from the start (audit LOW: TOCTOU — the old
    // create-then-chmod window exposed the key to concurrent readers).
    let mut opts = std::fs::OpenOptions::new();
    opts.write(true).create(true).truncate(true);
    #[cfg(unix)]
    {
        use std::os::unix::fs::OpenOptionsExt;
        opts.mode(0o600);
    }
    let mut f = opts
        .open(path)
        .map_err(|e| AetherError::storage(format!("create {}: {e}", path.display())))?;
    f.write_all(&bytes)
        .map_err(|e| AetherError::storage(format!("write {}: {e}", path.display())))?;
    Ok(())
}

#[cfg(test)]
mod tests {
    use super::*;
    use tempfile::TempDir;

    #[test]
    fn create_then_reload_is_the_same_ca() {
        let dir = TempDir::new().unwrap();
        let ca1 = CaManager::load_or_create(dir.path()).unwrap();
        let pem1 = ca1.ca_cert_pem();

        let ca2 = CaManager::load_or_create(dir.path()).unwrap();
        assert_eq!(pem1, ca2.ca_cert_pem(), "reload must reuse the stored CA");
        assert!(dir.path().join(CA_CERT_FILE).exists());
        assert!(dir.path().join(CA_KEY_FILE).exists());
    }

    #[test]
    fn incomplete_ca_dir_is_rejected() {
        let dir = TempDir::new().unwrap();
        std::fs::write(dir.path().join(CA_CERT_FILE), "junk").unwrap();
        assert!(CaManager::load_or_create(dir.path()).is_err());
    }

    #[test]
    fn leaf_chains_to_ca_for_names_and_ips() {
        let dir = TempDir::new().unwrap();
        let ca = CaManager::load_or_create(dir.path()).unwrap();
        for host in ["example.com", "10.0.0.1", "localhost"] {
            let leaf = ca.leaf_for(host).unwrap();
            assert_eq!(leaf.cert.len(), 2, "leaf + CA chain for {host}");
            assert_eq!(leaf.cert[1].as_ref(), ca.ca_cert_der().as_ref());
        }
        // cached second call returns the same object
        let again = ca.leaf_for("example.com").unwrap();
        assert!(Arc::ptr_eq(&ca.leaf_for("example.com").unwrap(), &again));
    }

    #[test]
    fn bracketed_ipv6_is_normalized() {
        let dir = TempDir::new().unwrap();
        let ca = CaManager::load_or_create(dir.path()).unwrap();
        let a = ca.leaf_for("[::1]").unwrap();
        let b = ca.leaf_for("::1").unwrap();
        assert!(Arc::ptr_eq(&a, &b));
    }
}
